import { mkdtempSync, readFileSync, writeFileSync } from "node:fs"; import { tmpdir } from "node:os"; import { join } from "node:path";
import { RUNTIME_COMMAND_ENVELOPE_VERSION } from "@moe/contracts"; import { afterEach, expect, it } from "vitest";
import { backupFileHash } from "./src/backups/backup-ports.js";
import { setEnvironmentVariable } from "./src/environment/environment-store.js";
import { MIGRATION_RECEIPT_VERSION, migrationReceiptId, readMigrationReceipt, recordMigrationReceipt } from "./src/repository/migrations/migration-receipt.js";
import { closeStores, openStore, PROJECT_ID as P } from "./src/review/review-test-fixtures.js";
import { deploymentInfrastructureFiles } from "./src/repository/deployment/deployment-infrastructure-templates.js";
import { recordDeployReceipt } from "./src/deployment/deploy-ledger.js";
import { DEPLOY_MIGRATION_DATABASE_VARIABLE } from "./src/deployment/deploy-migration-context.js";
import { createDockerDouble } from "./src/deployment/deploy-ports.js";
import { candidateContainerName as cn } from "./src/deployment/deploy-service.js";
import { createRollbackCommandHandler } from "./src/deployment/rollback-command.js";
afterEach(closeStores);
const clock = () => "2026-09-06T01:00:00.000Z", env = "production", dg = `sha256:${"b".repeat(64)}`;
const SA = "a".repeat(40), SB = "d".repeat(40), SD = "f".repeat(40), C = () => "c";
it("restoring rollback between target and first migrating successor", async () => {
  const store = openStore(), root = mkdtempSync(join(tmpdir(), "qa-"));
  const deploy = (id: string, sha: string) => { const r = recordDeployReceipt(store, { projectId: P, environment: env, sha, imageDigest: dg, decisionId: id, decidedAt: clock(), refusal: null, releaseDecision: null, url: null }); if (!r.ok) throw new Error(r.code); return r.receipt; };
  const migrate = async (id: string, sha: string, f: string) => recordMigrationReceipt(store, { applied: ["1700000000001_m.js"], backupRef: `${f}@sha256:${await backupFileHash(f)}`, decidedAt: clock(), environment: env, outcome: "APPLIED", projectId: P, receiptId: migrationReceiptId(P, id), refusal: null, requestId: id, sha, version: MIGRATION_RECEIPT_VERSION });
  const a = deploy("dep-a", SA), b = deploy("dep-b", SB), dumpB = join(root, "b.sql");
  writeFileSync(dumpB, "-- SCHEMA A\nCREATE TABLE a();\n"); await migrate("dep-b", SB, dumpB);
  expect(setEnvironmentVariable({ credential: C, now: clock, projectId: P, store }, { environment: env, name: DEPLOY_MIGRATION_DATABASE_VARIABLE, value: "postgres://x@db/app" })).toMatchObject({ ok: true });
  const dk = createDockerDouble({ proxyConfig: deploymentInfrastructureFiles("", []).get("docker/Caddyfile") ?? "", running: { app: "HEALTHY" }, imageDigest: dg,
    health: { [cn(env, SA, "rb-r")]: ["HEALTHY"], [cn(env, SB, "rb-b")]: ["HEALTHY"] } });
  const calls: string[] = [];
  const handler = createRollbackCommandHandler({ operatorPrincipalId: "op", projectId: P, store, clock, healthBudgetMs: 1, pollMs: 1, sleep: async () => {},
    ports: { build: dk.build, docker: dk.docker, ssh: dk.ssh, transfer: dk.transfer, target: () => ({ network: "n", sshTarget: null, url: null }), releaseDecision: () => null },
    environmentCredential: C, migrationWorkspace: root, backupPorts: { restoreDatabaseInto: async (_c: string, p: string) => { calls.push(p); } } });
  const send = (commandId: string, toReceiptRef: string) => handler({ principal: { principalId: "op", projectId: P, capabilities: ["goal.write"] },
    envelope: { commandId, commandKind: "deployment.rollback", correlationId: commandId, schemaVersion: RUNTIME_COMMAND_ENVELOPE_VERSION, expectedVersion: store.getAggregateVersion(P),
      targetAggregateId: P, requestDigest: "c".repeat(64), sessionCredential: "t", payload: { environment: env, toReceiptRef, restoreDatabase: true } } } as never);
  await send("rb-r", a.receiptId);
  expect(calls).toEqual([dumpB]);
  expect(readMigrationReceipt(store, P, "rb-r")).toBeNull();
  expect(store.getCommandDecision({ commandId: "rb-r", principalId: "daemon:rollback-restore", projectId: P })).not.toBeNull();
  deploy("dep-d", SD); const dumpD = join(root, "d.sql");
  writeFileSync(dumpD, readFileSync(dumpB, "utf8")); await migrate("dep-d", SD, dumpD);
  await send("rb-b", b.receiptId);
  expect(calls[1]).toBe(dumpD);
  expect(readFileSync(calls[1]!, "utf8")).toContain("SCHEMA A");
});
